<script setup lang="ts">
import {ref} from 'vue';import PageShell from '../../components/PageShell.vue';import {useCartStore} from '../../store/modules/cart';import {usePage} from '../../composables/usePage';import {request} from '../../utils/request';import {go,toast} from '../../utils/format'
const cart=useCartStore(),pets=ref<any[]>([]),addresses=ref<any[]>([]);const {loading,error,load}=usePage(async()=>{[pets.value,addresses.value]=await Promise.all([request('/owner/pets'),request('/owner/addresses')]);if(!cart.date){const d=new Date(Date.now()+86400000);cart.date=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}})
function toggle(id:number){cart.petIds=cart.petIds.includes(id)?cart.petIds.filter(x=>x!==id):[...cart.petIds,id]}
function next(){if(!cart.petIds.length||!cart.addressId)return toast('请选择宠物和服务地址');const start=Date.parse(cart.date+'T'+cart.start+':00+08:00'),end=Date.parse(cart.date+'T'+cart.end+':00+08:00');if(start<=Date.now()||end<=start||end-start>43200000)return toast('请选择未来时间，结束须晚于开始且不超过12小时');cart.resetKey();go('owner/booking-extra')}
</script><template><PageShell title="预约上门服务" back :loading="loading" :error="error" @retry="load"><view class="steps"><text class="on">01 选择服务</text><text>02 照护要求</text><text>03 确认预约</text></view><view class="title">这次，要照顾谁？</view><view class="section">选择毛孩子 <text class="link" @click="go('owner/petadd')">＋ 添加</text></view><view v-for="p in pets" :key="p.id" :class="['option', {selected:cart.petIds.includes(p.id)}]" @click="toggle(p.id)"><view class="row"><view class="row-start"><text style="font-size:28px">{{p.category==='DOG'?'🐕':'🐈'}}</text><view><view>{{p.name}}</view><text class="muted">{{p.breed||'可到宠物档案补充信息'}}</text></view></view><text class="checkbox">{{cart.petIds.includes(p.id)?'✓':''}}</text></view></view><view class="section">上门地址 <text class="link" @click="go('owner/addresses')">管理 ›</text></view><view v-for="a in addresses" :key="a.id" :class="['option',{selected:cart.addressId===a.id}]" @click="cart.addressId=a.id"><view>{{a.district}} · {{a.address}}</view><text class="muted">{{a.contact_name}} {{a.phone}}</text></view><view v-if="!addresses.length" class="notice warning" @click="go('owner/addresses')">请先添加服务地址 ›</view><view class="section">预约日期与时段</view><view class="card"><picker mode="date" :value="cart.date" @change="cart.date=$event.detail.value"><view class="menu-item">服务日期 <text>{{cart.date}} ›</text></view></picker><view class="grid" style="margin-top:12px"><picker mode="time" :value="cart.start" @change="cart.start=$event.detail.value"><view class="field" style="padding:12px">开始 {{cart.start}}</view></picker><picker mode="time" :value="cart.end" @change="cart.end=$event.detail.value"><view class="field" style="padding:12px">结束 {{cart.end}}</view></picker></view><text class="muted">基础服务包含喂食换水、清洁、陪伴与现场记录。</text></view><button class="primary" @click="next">下一步 · 照护要求 →</button></PageShell></template>
